package com.messagingapp.service;
import com.messagingapp.model.*; import com.messagingapp.repository.*; import java.time.Instant; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.web.server.ResponseStatusException;
@Service public class MessagingService { private final UserRepository users; private final ConversationRepository conversations; private final MessageRepository messages; public MessagingService(UserRepository u,ConversationRepository c,MessageRepository m){users=u;conversations=c;messages=m;} public List<User> contacts(String me){return users.findAll().stream().filter(u->!u.id().equals(me)).toList();} public Conversation direct(String me,String other){if(me.equals(other)||!users.existsById(other))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Valid recipient required");var ids=List.of(me,other).stream().sorted().toList();var key=String.join(":",ids);return conversations.findByParticipantKey(key).orElseGet(()->conversations.save(new Conversation(null,key,ids,Instant.now())));} public List<Conversation> all(String me){return conversations.findAll().stream().filter(c->c.participantIds().contains(me)).toList();} public List<Message> messages(String me,String id){member(me,id);return messages.findByConversationIdOrderByCreatedAtAsc(id);} public Message send(String me,String id,String content){member(me,id);if(content==null||content.isBlank()||content.length()>2000)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Message must be 1-2000 characters");return messages.save(new Message(null,id,me,content.trim(),Instant.now(),Message.Status.SENT));} private void member(String me,String id){var c=conversations.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Conversation not found"));if(!c.participantIds().contains(me))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Not a conversation member");} }
